    // localNamedVertex returns the index of the vertex representing
    // named, or -1 if named doesn't need representation.
    int rec::localNamedVertex(monoGraph* w, Package* pkg, Named* named)
    {
        auto obj = rec::Obj(gocpp::recv(named));
        if(rec::Pkg(gocpp::recv(obj)) != pkg)
        {
            // imported type
            return - 1;
        }

        auto root = rec::Scope(gocpp::recv(pkg));
        if(rec::Parent(gocpp::recv(obj)) == root)
        {
            // package scope, no ambient type parameters
            return - 1;
        }

        if(auto [idx, ok] = w->nameIdx[obj]; ok)
        {
            return idx;
        }

        auto idx = - 1;

        // Walk the type definition's scope to find any ambient type
        // parameters that it's implicitly parameterized by.
        for(auto scope = rec::Parent(gocpp::recv(obj)); scope != root; scope = rec::Parent(gocpp::recv(scope)))
        {
            for(auto [gocpp_ignored, elem] : scope->elems)
            {
                {
                    auto [elem_tmp, ok] = gocpp::getValue<TypeName*>(elem);
                    if(auto& elem = elem_tmp; ok && ! rec::IsAlias(gocpp::recv(elem)) && cmpPos(rec::Pos(gocpp::recv(elem)), rec::Pos(gocpp::recv(obj))) < 0)
                    {
                        if(auto [tpar, ok] = gocpp::getValue<TypeParam*>(rec::Type(gocpp::recv(elem))); ok)
                        {
                            if(idx < 0)
                            {
                                idx = len(w->vertices);
                                w->vertices = append(w->vertices, gocpp::Init<monoVertex>([=](auto& x) {
                                    x.obj = obj;
                                }));
                            }

                            rec::addEdge(gocpp::recv(w), idx, rec::typeParamVertex(gocpp::recv(w), tpar), 1, rec::Pos(gocpp::recv(obj)), tpar);
                        }
                    }
                }
            }
        }

        if(w->nameIdx == nullptr)
        {
            w->nameIdx = gocpp::make(gocpp::Tag<gocpp::map<TypeName*, int>>());
        }
        w->nameIdx[obj] = idx;
        return idx;
    }

    // typeParamVertex returns the index of the vertex representing tpar.
    int rec::typeParamVertex(monoGraph* w, TypeParam* tpar)
    {
        if(auto [x, ok] = w->canon[tpar]; ok)
        {
            tpar = x;
        }

        auto obj = rec::Obj(gocpp::recv(tpar));

        if(auto [idx, ok] = w->nameIdx[obj]; ok)
        {
            return idx;
        }

        if(w->nameIdx == nullptr)
        {
            w->nameIdx = gocpp::make(gocpp::Tag<gocpp::map<TypeName*, int>>());
        }

        auto idx = len(w->vertices);
        w->vertices = append(w->vertices, gocpp::Init<monoVertex>([=](auto& x) {
            x.obj = obj;
        }));
        w->nameIdx[obj] = idx;
        return idx;
    }

    void rec::addEdge(monoGraph* w, int dst, int src, int weight, token::Pos pos, golang::types::Type typ)
    {
        // TODO(mdempsky): Deduplicate redundant edges?
        w->edges = append(w->edges, gocpp::Init<monoEdge>([=](auto& x) {
            x.dst = dst;
            x.src = src;
            x.weight = weight;
            x.pos = pos;
            x.typ = typ;
        }));
    }

